 const oid=await scalar('select public.place_affiliate_order($1,$2,$3,$4,$5,$6,null)',[JSON.stringify([{product_id:allureProduct,quantity}]),'QA Buyer','00000000','QA delivery address','QA City',key('funded-'+label)]);
 assert.equal(Number(await scalar('select count(*) from public.shopping_reward_events where order_id=$1',[oid])),0);
 await as('admin');await query('select public.admin_confirm_order_payment($1)',[oid]);const count=Number(await scalar('select count(*) from public.mio_ledger where source_order_id=$1',[oid]));await query('select public.admin_confirm_order_payment($1)',[oid]);assert.equal(Number(await scalar('select count(*) from public.mio_ledger where source_order_id=$1',[oid])),count);
 const ev=(await query('select * from public.shopping_reward_events where order_id=$1',[oid])).rows[0];
 assert.equal(Number(ev.funded_pkr),398.75*quantity);assert.ok(Number(ev.direct_generation_mio)<=Number(ev.bv)*0.55);assert.ok(Number(ev.single_line_mio)<=Number(ev.bv)*0.10);
 assert.ok((Number(ev.direct_generation_mio)+Number(ev.single_line_mio)+Number(ev.binary_reserve_mio))*300<=Number(ev.funded_pkr));
 assert.equal(Number(await scalar("select sum(amount_pkr) from public.commission_allocations a join public.order_items i on i.id=a.order_item_id where i.order_id=$1 and share_kind='company'",[oid])),79.75*quantity);
 assert.equal(Number(await scalar("select sum(amount) from public.point_ledger where member_id=$1 and point_type='PPV'",[buyer])),Number((beforePpv+1.1962*quantity).toFixed(4)));
 assert.equal(Number(await scalar("select count(*) from public.point_ledger where member_id=$1 and source_order_id=$2 and point_type in('BV','DP','GP','BRP')",[buyer,oid])),4);
 assert.equal(Number(await scalar('select count(*) from public.bonus_transactions b join public.package_activations a on a.id=b.source_activation_id where a.source=\'SHOPPING_PPV\' and a.source_reference=$1',[oid])),0);
 confirmedShopping.push(oid);pass('Funded '+label+': source caps, four network point types, company sale share and retry conservation');
